/*
 * A304501  Solution (b(n)) of the system of complementary equations defined
 *          in Comments.
 * https://oeis.org/A304501
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   Sequence b(n) is generated by the complementary recurrence
 *            described in the OEIS comments: a(0)=1, b(0)=2,
 *            c(0)=a(0)+2*b(0). For n>0: a(n) = least positive integer not yet
 *            used by any of the sequences a, b, c b(n) = least positive
 *            integer not yet used c(n) = a(n) + 2*b(n) The three sequences
 *            toge...
 * Range:     u8 n <= 55, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   ensure_b_cap
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <string.h>
#include "../utils/ensure_b_cap.h"

/* Dynamic array for used flags (0 or 1) */
static void ensure_used_cap(idx_t idx) {
    static size_t used_cap = 0;
    static uint8_t *used = NULL;
    if (used_cap <= idx) {
        size_t old_cap = used_cap;
        size_t new_cap = old_cap ? old_cap * 2 : 16;
        while (new_cap <= idx) new_cap *= 2;
        uint8_t *tmp = (uint8_t *)realloc(used, new_cap * sizeof(uint8_t));
        used = tmp;
        /* zero new area */
        if (new_cap > old_cap)
            memset(used + old_cap, 0, (new_cap - old_cap) * sizeof(uint8_t));
        used_cap = new_cap;
    }
}

/* The main function required by the problem statement */
seq_t a(idx_t n) {
    /* static state across calls */
    static seq_t *b_vals = NULL;          /* sequence b values */
    static size_t b_cap = 0;              /* capacity of b_vals */
    static size_t b_len = 0;              /* number of values stored in b_vals */
    static uint8_t *used = NULL;          /* bitmap of used integers, 0/1 */
    static size_t used_cap = 0;           /* capacity of used bitmap */
    static idx_t next_candidate = 1;      /* next integer to try for a or b */

    /* Allocate or grow b_vals if needed */
    if (b_len == 0 && b_cap == 0) {
        b_cap = 16;
        b_vals = (seq_t *)malloc(b_cap * sizeof(seq_t));
    }

    while (b_len <= (size_t)n) {
        /* --- find a(n) --- */
        idx_t cand = next_candidate;
        while (1) {
            if (cand >= used_cap) {
                size_t old_cap = used_cap;
                size_t new_cap = old_cap ? old_cap * 2 : 16;
                while (new_cap <= cand) new_cap *= 2;
                uint8_t *tmp = (uint8_t *)realloc(used, new_cap * sizeof(uint8_t));
                used = tmp;
                if (new_cap > old_cap)
                    memset(used + old_cap, 0, (new_cap - old_cap));
                used_cap = new_cap;
            }
            if (!used[cand])
                break;
            ++cand;
        }
        seq_t a_val = (seq_t)cand;
        used[cand] = 1;
        ++cand;
        next_candidate = cand;

        /* --- find b(n) --- */
        cand = next_candidate;
        while (1) {
            if (cand >= used_cap) {
                size_t old_cap = used_cap;
                size_t new_cap = old_cap ? old_cap * 2 : 16;
                while (new_cap <= cand) new_cap *= 2;
                uint8_t *tmp = (uint8_t *)realloc(used, new_cap * sizeof(uint8_t));
                used = tmp;
                if (new_cap > old_cap)
                    memset(used + old_cap, 0, (new_cap - old_cap));
                used_cap = new_cap;
            }
            if (!used[cand])
                break;
            ++cand;
        }
        seq_t b_val = (seq_t)cand;
        used[cand] = 1;
        ++cand;
        next_candidate = cand;

        /* --- compute c(n) --- */
        seq_t c_val = a_val + 2 * b_val;
        idx_t c_idx = (idx_t)c_val;          /* safe cast for n up to ~10k */
        if (c_idx >= used_cap) {
            size_t old_cap = used_cap;
            size_t new_cap = old_cap ? old_cap * 2 : 16;
            while (new_cap <= c_idx) new_cap *= 2;
            uint8_t *tmp = (uint8_t *)realloc(used, new_cap * sizeof(uint8_t));
            used = tmp;
            if (new_cap > old_cap)
                memset(used + old_cap, 0, (new_cap - old_cap));
            used_cap = new_cap;
        }
        used[c_idx] = 1;

        /* --- store b(n) --- */
        if (b_len == b_cap) {
            b_cap *= 2;
            seq_t *tmp = (seq_t *)realloc(b_vals, b_cap * sizeof(seq_t));
            b_vals = tmp;
        }
        b_vals[b_len++] = b_val;
    }

    return b_vals[(size_t)n];
}
